const categories=['All Apparel','Polos','T-Shirts','Hoodies','Quarter Zips','Jackets','Vests','Shirts & Blouses'];
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}
let bag=read('dycem-bag-v2',[]),requests=read('dycem-requests',[]),category='All Apparel',gender='All',fabric=null,selection={},lastFocus;const cardColors={};
function persist(){try{localStorage.setItem('dycem-bag-v2',JSON.stringify(bag));localStorage.setItem('dycem-requests',JSON.stringify(requests));return true}catch{return false}}
function dcLogoAsset(color){return `assets/dycem-dc-${color==='black'?'white':'dark'}.png`}
function garment(p,color,logo='dycem',ink='red',showLogo=true){
 const pos=p.logoPosition,ratio=p.imageAspectRatio||1;
 const position=`left:${pos.x}%;top:${pos.y}%;width:${pos.w}%`;
 const frame=`width:${Math.min(1,ratio)*100}%;height:${Math.min(1,1/ratio)*100}%`;
 const artwork=logo==='dc'?`<span class="garment-logo dc-logo-artwork" style="${position}"><img src="${dcLogoAsset(color)}" alt="Full-color Dycem Data Centers logo, ${color==='black'?'white':'dark'} lettering, wearer's left chest"></span>`:`<span class="garment-logo logo-mask ${ink}" style="${position}" role="img" aria-label="Dycem logo in ${ink}, wearer's left chest"></span>`;
 return `<div class="product-image" data-kind="${p.id}"><div class="garment-photo" style="${frame}"><img src="assets/${p.id}-${color}.${p.imageExtension||'png'}" alt="${esc(p.brand+' '+p.name)}, ${color} fabric" loading="lazy">${showLogo?artwork:''}</div></div>`
}

function renderCatalog(){
 const matchesFit=p=>(gender==='All'||p.gender===gender)&&(!fabric||p.colors.some(c=>c.value===fabric));
 const n=c=>products.filter(p=>(c==='All Apparel'||p.category===c)&&matchesFit(p)).length;
 $('#navCategories').innerHTML=categories.map(c=>`<button class="category ${category===c?'active':''}" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('');
 $('#sideCategories').innerHTML=categories.map(c=>`<button class="side-category ${category===c?'active':''}" data-category="${c}" aria-pressed="${category===c}">${c}<b>${n(c)}</b></button>`).join('');
 const q=$('#search').value.toLowerCase();let list=products.filter(p=>(category==='All Apparel'||p.category===category)&&matchesFit(p)&&(p.brand+' '+p.name+' '+p.code).toLowerCase().includes(q));
 if($('#sort').value!=='featured')list.sort((a,b)=>a.name.localeCompare(b.name)*($('#sort').value==='az'?1:-1));
 $('#resultCount').textContent=list.length;$('#fitCaption').textContent=gender==='All'?" / Men's & women's collection":` / ${gender==='Men'?"Men's":"Women's"} collection`;
 $('#grid').innerHTML=list.length?list.map(p=>{const c=fabric||cardColors[p.id]||p.defaultColor;return `<article class="product-card"><button class="product-open" data-product="${p.id}" aria-label="View ${esc(p.name)}">${garment(p,c,'dycem','red',false)}<span class="view-label">View product</span><div class="product-info"><span class="tag">${esc(p.type)}</span><h3>${esc(p.name)}</h3><p>${p.gender==='Men'?"Men's":"Women's"} · ${p.sizeRange}</p></div></button><div class="swatches">${p.colors.map(x=>`<button class="swatch ${c===x.value?'selected':''}" data-swatch="${p.id}" data-color="${x.value}" aria-label="${esc(p.name)} in ${x.name}" aria-pressed="${c===x.value}"><i class="dot ${x.value}"></i></button>`).join('')}<span class="swatch-caption">${p.colors.length===1?'Black only':'Black / White'}</span></div></article>`}).join(''):'<div class="empty"><h3>No matching products</h3><p>Try a different fit, color, or department.</p><button class="secondary" id="resetSearch">Clear filters</button></div>';
 document.querySelectorAll('.color-filter').forEach(b=>b.setAttribute('aria-pressed',b.dataset.color===fabric));$('#fitFilter').value=gender;
}

function updateCount(){$('#cartCount').textContent=bag.reduce((s,i)=>s+i.qty,0)}
function openModal(html){if(!$('#modal').open)lastFocus=document.activeElement;$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
function closeModal(){$('#modal').close();lastFocus?.focus()}
$('.close').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function itemInk(i){return 'red'}
function logoDescription(i){return i.logo==='dc'?`Dycem Data Centers · full color, ${i.color==='black'?'white':'dark'} lettering`:`Dycem · ${itemInk(i)} logo`}
bag=bag.filter(i=>products.some(p=>p.id===i.id)).map(i=>({...i,logo:i.logo||'dycem',ink:itemInk(i)}));
function detail(id){const p=products.find(p=>p.id===id),color=fabric||cardColors[id]||p.defaultColor;selection={id,color,size:'',qty:1,logo:'dycem',ink:'red'};renderDetail()}
function editItem(key){selection={...bag.find(i=>i.key===key)};renderDetail()}
function logoControls(){return `<fieldset class="logo-picker"><legend>Choose your logo</legend><div class="logo-option-row">${[['dycem','Dycem'],['dc','Dycem Data Centers']].map(([v,n])=>`<button type="button" class="choice logo-choice ${selection.logo===v?'selected':''}" data-detail-logo="${v}" aria-pressed="${selection.logo===v}">${v==='dc'?'<img class="dc-choice-artwork" src="assets/dycem-dc-color.png" alt="Dycem Data Centers">':'<span class="logo-mask" aria-hidden="true"></span>'}${n}</button>`).join('')}</div>${selection.logo==='dycem'?`<p class="field">Logo color</p><div class="choice-row">${['red'].map(v=>`<button type="button" class="choice ${itemInk(selection)===v?'selected':''}" data-detail-ink="${v}" aria-pressed="${itemInk(selection)===v}"><i class="dot ${v}"></i>${v==='red'?'Red':'White'}</button>`).join('')}</div>`:'<p class="note">Full-color teal and green badge. The Dycem lettering adapts to your fabric color.</p>'}</fieldset>`}

function renderDetail(){
 const p=products.find(p=>p.id===selection.id),color=p.colors.find(c=>c.value===selection.color);
 openModal(`<div class="detail">${garment(p,selection.color,selection.logo,itemInk(selection))}<div><p class="eyebrow">${esc(p.brand)} / ${p.code} / ${p.gender==='Men'?"MEN'S":"WOMEN'S"}</p><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><label class="field">Fabric color: ${esc(color.name)}</label><div class="choice-row">${p.colors.map(c=>`<button class="choice ${selection.color===c.value?'selected':''}" data-detail-color="${c.value}" aria-pressed="${selection.color===c.value}"><i class="dot ${c.value}"></i>${esc(c.name)}</button>`).join('')}</div>${p.colors.length===1?`<p class="product-meta">${esc(p.colorNote||'Available in black for this collection.')}</p>`:''}${logoControls()}<div class="size-label"><label class="field">Select your size</label><button class="small-link" id="viewSizeChart">View size chart</button></div><div class="choice-row sizes">${p.sizes.map(z=>`<button class="choice ${selection.size===z?'selected':''}" data-size="${z}" aria-pressed="${selection.size===z}">${z}</button>`).join('')}</div><div class="add-row"><input class="quantity" id="detailQty" type="number" value="${selection.qty}" min="1" step="1" aria-label="Quantity"><button class="primary" id="addToBag">${selection.key?'Save changes':'Add to bag'}</button></div><div class="error" id="detailError" role="alert"></div><p class="note">Your chosen logo appears on the wearer's left chest. Preview placement is approximate; final placement is confirmed before production.</p><a class="source-link" href="${esc(p.source)}" target="_blank" rel="noopener">View product at ${esc(p.supplier||'Heavy Press')}</a></div></div><section class="product-specs"><h3>Product details</h3><ul>${p.details.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></section><section id="sizeChart" class="size-chart" tabindex="-1"><h3>Size chart</h3><p class="intro">${esc(p.brand)} ${p.code} · Supplier sizing · measurements in inches</p><div class="table-scroll" role="region" aria-label="${esc(p.name)} size chart" tabindex="0"><table><thead><tr>${p.sizeRows[0].map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${p.sizeRows.slice(1).map(row=>`<tr>${row.map((c,i)=>i===0?`<th scope="row">${esc(c)}</th>`:`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="product-meta">Sizing is reproduced from the linked supplier page. Final stock is confirmed when the order is placed.</p></section>`)
}

function addToBag(){const qty=Number($('#detailQty').value);if(!products.find(p=>p.id===selection.id).sizes.includes(selection.size)){$('#detailError').textContent='Please select a size.';return}if(!Number.isSafeInteger(qty)||qty<1){$('#detailError').textContent='Enter a whole quantity of 1 or more.';return}const editing=!!selection.key;const old=bag.find(i=>i.key!==selection.key&&i.id===selection.id&&i.color===selection.color&&i.size===selection.size&&i.logo===selection.logo&&itemInk(i)===itemInk(selection));bag=bag.filter(i=>i.key!==selection.key);if(old)old.qty+=qty;else bag.push({...selection,ink:itemInk(selection),qty,key:selection.key||crypto.randomUUID()});persist();updateCount();if(editing)renderBag();else closeModal();toast(editing?'Item updated':'Added to your bag')}
function renderBag(){openModal(`<p class="eyebrow">YOUR TEAM GEAR</p><h2 class="dialog-heading">My bag</h2><p class="intro">Review your items before preparing your approval request.</p>${bag.length?bag.map(i=>{const p=products.find(p=>p.id===i.id);return `<div class="bag-row">${garment(p,i.color,i.logo,itemInk(i))}<div class="bag-info"><strong>${p.name}</strong><p>${i.color[0].toUpperCase()+i.color.slice(1)} / Size ${i.size}<br>${logoDescription(i)}</p><button class="small-link" data-edit="${i.key}">Edit choices</button> <button class="remove" data-remove="${i.key}">Remove</button></div><input class="quantity" type="number" min="1" step="1" value="${i.qty}" data-qty="${i.key}" aria-label="Quantity for ${esc(p.name)} ${i.size}"></div>`}).join('')+`<div class="actions"><button class="secondary" data-close>Continue shopping</button><button class="primary" id="checkoutBtn">Continue to checkout</button></div><p class="product-meta">Supplier catalog. Final prices and availability are confirmed before ordering.</p>`:'<div class="empty"><h3>Your bag is empty</h3><p>Choose your gear and select a size to get started.</p><button class="primary" data-close>Explore the collection</button></div>'}`)}
function checkoutView(){openModal(`<p class="eyebrow">MANAGER APPROVAL</p><h2 class="dialog-heading">Review your Dycem gear.</h2><p class="intro">Your logo selections are saved with each item. Add your details to prepare your approval request. No payment is taken.</p><form id="checkoutForm"><div class="checkout-layout"><div><div class="form-grid"><label class="field">Your name<input name="name" autocomplete="name" required placeholder="First and last name" maxlength="100"></label><label class="field">Work email<input name="email" type="email" autocomplete="email" required placeholder="you@dycem.com" maxlength="150"></label></div><label class="field">Manager's email<input name="manager" type="email" required placeholder="manager@dycem.com" maxlength="150"></label><label class="field">Notes <span class="subtle">(optional)</span><textarea name="notes" placeholder="Event, delivery needs, or anything else to know" maxlength="1500"></textarea></label></div><aside class="order-summary"><h3>Your request</h3>${bag.map(i=>{const p=products.find(p=>p.id===i.id);return `<div class="bag-row">${garment(p,i.color,i.logo,itemInk(i))}<div class="bag-info"><strong>${esc(p.name)}</strong><p>${i.color} / ${i.size} / Qty ${i.qty}<br>${logoDescription(i)}</p></div></div>`}).join('')}<hr><p><strong>Placement</strong><br>Wearer's left chest on every item.</p><p class="note"><strong>Preview mode</strong><br>This saves a demo request on this device. It does not send an email, notify a manager, or place an order.</p><label class="check-field"><input type="checkbox" required> <span>I've checked the sizes, fabric colors, and logo choices.</span></label><button type="submit" class="primary full">Submit for approval</button><div class="error" id="checkoutError" role="alert"></div><button type="button" class="small-link" id="backToBag">Back to bag</button></aside></div></form>`);$('#checkoutForm').onsubmit=submitOrder}
function saveRequest(r){requests.unshift(r);if(!persist()){requests.shift();return false}return true}
function submitOrder(e){e.preventDefault();const f=new FormData(e.target);const r={id:'DYC-'+Date.now().toString(36).toUpperCase(),createdAt:new Date().toISOString(),type:'Apparel request',status:'demo_pending_approval',demo:true,submitted:false,name:f.get('name').trim(),email:f.get('email').trim(),managerEmail:f.get('manager').trim(),notes:f.get('notes').trim(),items:bag.map(i=>({...i,name:products.find(p=>p.id===i.id).name,productCode:products.find(p=>p.id===i.id).code,supplierProductId:products.find(p=>p.id===i.id).supplierId,supplierColorId:products.find(p=>p.id===i.id).colors.find(c=>c.value===i.color).supplierColorId,source:products.find(p=>p.id===i.id).source,logo:i.logo,logoColor:i.logo==='dc'?(i.color==='black'?'full_color_white_wordmark':'full_color_dark_wordmark'):itemInk(i),...(i.logo==='dc'?{logoAsset:dcLogoAsset(i.color)}:{}),placement:'wearer_left_chest'}))};if(!r.name){$('#checkoutError').textContent='Please enter your name.';return}if(!saveRequest(r)){$('#checkoutError').textContent='This browser could not save your request. Enable local storage and try again.';return}bag=[];persist();updateCount();showSuccess(r)}
function showSuccess(r){openModal(`<div class="success"><span class="check-icon">✓</span><p class="eyebrow">${esc(r.id)}</p><h2 class="dialog-heading">Demo request saved.</h2><p>Your ${r.type==='Apparel request'?'apparel request':'product suggestion'} is ready for review in this preview. You can find it under My requests or download a copy.</p><p class="note">Saved on this device only. Nothing has been sent to your manager or supplier. Live approval routing will be connected in the final ordering platform.</p><div class="actions"><button class="secondary" data-download="${r.id}">Download request</button><button class="primary" data-close>Back to collection</button></div></div>`)}
function requestNew(){openModal(`<div class="request-form"><p class="eyebrow">GROW THE COLLECTION</p><h2 class="dialog-heading">Request something new.</h2><p class="intro">Tell us what you'd like to see in the team collection.</p><form id="requestForm"><div class="form-grid"><label class="field">Your name<input name="name" required maxlength="100" autocomplete="name" placeholder="First and last name"></label><label class="field">Work email<input name="email" required type="email" maxlength="150" autocomplete="email" placeholder="you@dycem.com"></label></div><label class="field">What would you like?<input name="item" required maxlength="150" placeholder="For example, a lightweight jacket"></label><label class="field">Product link <span class="subtle">(optional)</span><input name="url" type="url" placeholder="https://" maxlength="1000"></label><label class="field">Tell us more<textarea name="reason" required placeholder="How would you use it? Any preferred style or features?" maxlength="1500"></textarea></label><p class="note">New items should be black or white, with a red Dycem logo or full-color Dycem Data Centers logo on the wearer's left chest. This demo saves your suggestion on this device only.</p><button class="primary full">Save demo suggestion</button><div class="error" id="requestError" role="alert"></div></form></div>`);$('#requestForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const r={id:'DYC-'+Date.now().toString(36).toUpperCase(),createdAt:new Date().toISOString(),type:'Product suggestion',status:'demo_pending_review',demo:true,submitted:false,name:f.get('name').trim(),email:f.get('email').trim(),item:f.get('item').trim(),url:f.get('url'),reason:f.get('reason').trim()};if(!r.name||!r.item||!r.reason){$('#requestError').textContent='Please complete the required fields.';return}if(saveRequest(r))showSuccess(r);else $('#requestError').textContent='Unable to save locally. Please enable local storage and try again.'}}
function history(){openModal(`<p class="eyebrow">SAVED ON THIS DEVICE</p><h2 class="dialog-heading">My requests</h2><p class="intro">Your demo apparel requests and product suggestions. Nothing has been sent.</p>${requests.length?requests.map(r=>`<div class="history-item"><div><strong>${esc(r.type==='Product suggestion'?r.item:r.type)}</strong><p>${esc(r.id)} · ${new Date(r.createdAt).toLocaleDateString()}<br>${r.items?r.items.reduce((s,i)=>s+i.qty,0)+' items · ':''}${esc(r.name)}</p><span class="status">Demo · ${r.type==='Apparel request'?'Awaiting approval':'Awaiting review'}</span></div><button class="secondary" data-download="${r.id}">Download</button></div>`).join(''):'<div class="empty"><h3>No requests yet</h3><p>Your saved demo requests will appear here.</p></div>'}`)}
function download(id){const r=requests.find(r=>r.id===id);const url=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=r.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.category){category=d.category;renderCatalog()}if(d.product)detail(d.product);if(d.swatch){cardColors[d.swatch]=d.color;fabric=null;renderCatalog()}if(b.classList.contains('color-filter')){fabric=fabric===d.color?null:d.color;renderCatalog()}if(d.detailColor){selection.qty=Number($('#detailQty').value)||1;selection.color=d.detailColor;if(selection.color==='white')selection.ink='red';renderDetail()}if(d.size){selection.qty=Number($('#detailQty').value)||1;selection.size=d.size;renderDetail()}if(d.remove){bag=bag.filter(i=>i.key!==d.remove);persist();updateCount();renderBag()}if(d.edit)editItem(d.edit);if(d.detailLogo||d.detailInk){selection.qty=Number($('#detailQty').value)||1;if(d.detailLogo)selection.logo=d.detailLogo;if(d.detailInk)selection.ink=d.detailInk;renderDetail()}if('close'in d)closeModal();if(d.download)download(d.download);switch(b.id){case'cartBtn':case'backToBag':renderBag();break;case'addToBag':addToBag();break;case'checkoutBtn':checkoutView();break;case'requestSide':case'requestBottom':requestNew();break;case'historyBtn':history();break;case'viewSizeChart':$('#sizeChart').scrollIntoView({behavior:'smooth',block:'start'});$('#sizeChart').focus({preventScroll:true});break;case'resetSearch':category='All Apparel';gender='All';fabric=null;$('#search').value='';renderCatalog();break}});
document.addEventListener('change',e=>{if(e.target.dataset.qty){const i=bag.find(i=>i.key===e.target.dataset.qty),n=Number(e.target.value);if(Number.isSafeInteger(n)&&n>0){i.qty=n;persist();updateCount()}else{e.target.value=i.qty;toast('Enter a whole quantity of 1 or more.')}}});$('#fitFilter').onchange=e=>{gender=e.target.value;renderCatalog()};$('#search').oninput=renderCatalog;$('#sort').onchange=renderCatalog;$('.brand').onclick=e=>{e.preventDefault();category='All Apparel';gender='All';fabric=null;$('#search').value='';renderCatalog();window.scrollTo({top:0,behavior:'smooth'})};renderCatalog();updateCount();
